```

**TypeScript**



```typescript
import { Mistral } from "@mistralai/mistralai";
import fs from "fs";

const apiKey = process.env["MISTRAL_API_KEY"];

const client = new Mistral({ apiKey: apiKey });

// If local document, upload and retrieve the signed url
const uploaded_pdf = await client.files.upload({
    file: {
        fileName: "local_audio.mp3",
        content: fs.readFileSync("local_audio.mp3"),
        },
    purpose: "audio",
});
const signedUrl = await client.files.getSignedUrl({
    fileId: uploaded_pdf.id,
});

// Get the transcription
const transcriptionResponse = await client.audio.transcriptions.complete({
    model: "voxtral-mini-latest",
    fileUrl: signedUrl.url,
    // language: "en"
});
```

**cURL**

**Upload the Audio File**

```bash
curl --location https://api.mistral.ai/v1/files \
  --header "Authorization: Bearer $MISTRAL_API_KEY" \
  --form purpose="audio" \
  --form file="@local_audio.mp3"
```

**Get the Signed URL**

```bash
curl --location "https://api.mistral.ai/v1/files/$id/url?expiry=24" \
    --header "Accept: application/json" \
    --header "Authorization: Bearer $MISTRAL_API_KEY"
```

**Send Transcription Request**

```bash
curl --location 'https://api.mistral.ai/v1/audio/transcriptions' \
    --header "x-api-key: $MISTRAL_API_KEY" \
    --form 'file_url="<signed_url>"' \
    --form 'model="voxtral-mini-latest"'
```

**Send Transcription Request with Language defined**



[6] https://docs.mistral.ai/studio/audio/speech_to_text/offline_transcription#transcription
Offline > Offline Transcription > Transcription > Transcribe any Audio
Offline > Offline Transcription > Transcription > Transcribe any Audio

**TypeScript**

```typescript
import { Mistral } from "@mistralai/mistralai";
import * as fs from "fs";
async function main() {
    const apiKey = process.env["MISTRAL_API_KEY"];
    if (!apiKey) {
        throw new Error("MISTRAL_API_KEY is not set in environment variables");
    }

    const model = "voxtral-mini-latest";
    const client = new Mistral({ apiKey: apiKey });

    try {
        // Upload local audio file and get signed URL
        const uploadedAudio = await client.files.upload({
            file: {
                fileName: "local_audio.mp3",
                content: fs.readFileSync("local_audio.mp3"),
            },
            purpose: "audio",
        });

        const signedUrl = await client.files.getSignedUrl({
            fileId: uploadedAudio.id,
        });

        // Perform transcription with diarization
        const response = await client.audio.transcriptions.complete({
            model: model,
            fileUrl: signedUrl.url,
            diarize: true,
            timestampGranularities: ["segment"],
        });

        // Print results with speaker diarization
        for (const segment of response.segments) {
            const speaker = segment.speaker_id || "unknown";
            console.log(
                `[${segment.start.toFixed(1)}s → ${segment.end.toFixed(1)}s] ${speaker}: ${segment.text.trim()}`
            );
        }
    } catch (error) {
        console.error("Error during transcription:", error);
        throw error;
    }
}

main().catch(console.error);
```

